    X_integrate[7] = X[7] + dt*(X[6]*tmp[16] - tmp[17]*tmp[20] + tmp[18]*tmp[19]);
    X_integrate[8] = X[8] + dt*(X[9]*tmp[16] + tmp[17]*tmp[21] - tmp[19]*tmp[22]);
    X_integrate[9] = X[9] + dt*(-X[8]*tmp[16] + tmp[17]*tmp[22] + tmp[19]*tmp[21]);
    X_integrate[10] = X[10];
    X_integrate[11] = X[11];
